n-20261014'\\n    prefix='.evidence/'+request['task_id']+'/'\\n    assert args.request.startswith(prefix) and args.output.startswith(prefix)\\n    output=Path(args.output)\\n    assert not output.is_absolute() and '..' not in output.parts and output.suffix=='.json'\\n    parent=REPO\\n    for part in output.parts[:-1]:\\n        parent=parent/part\\n        assert not parent.is_symlink() and parent.is_dir()\\n    target=REPO/output;assert target.parent.is_dir() and not target.exists()\\n    gate.validate_request(REPO,request)\\n    own_sha=digest(Path(__file__));validator_sha=digest(Path(gate.__file__))\\n    if args.consume:\\n        assert args.consume.startswith(prefix)\\n        envelope=json.loads(gate.exact_file(REPO,args.consume,('.evidence',)).read_text())\\n        transport=json.loads(gate.exact_file(REPO,str(Path(args.consume).with_suffix('.transport.json')),('.evidence',),max_bytes=8*1024*1024).read_text())\\n        assert envelope['validator_sha256']==validator_sha\\n        record=gate.consumption_record(request,envelope,transport,own_sha)\\n        gate.validate_request(REPO,request)\\n        marker=target.parent/(hashlib.sha256(request['request_id'].encode()).hexdigest()+'.consumed.json')\\n        save(marker,record);save(target,record)\\n        print(json.dumps({'consumption':str(target),'status':record['status'],'execution_authorized':False}));return\\n    for prior in target.parent.glob('*.attempt.json'):\\n        assert json.loads(prior.read_text())['request_id']!=request['request_id'],'existing attempt: reconcile, do not resend'\\n    marker=target.parent/(hashlib.sha256(request['request_id'].encode()).hexdigest()+'.attempt.json')\\n    save(marker,{'request_id':request['request_id'],'baseline':request['baseline'],'status':'ATTEMPTED_UNKNOWN','runner_sha256':own_sha,'validator_sha256':validator_sha})\\n    template={k:request[k] for k in ('request_id','task_id','owner','kind','baseline')}\\n    template.update(verdict='<choose PASS/REWORK/NEED_EVIDENCE/NEED_DECISION>',\\n        findings=[{'claim':c,'evidence':'<actual supplied file/function/field evidence; do not invent>','assessment':'<choose supported/contradicted/insufficient>'} for c in request['claims']],\\n        next_safe_step='<required concrete nonempty safe suggestion, even for PASS>')\\n    system=gate.SYSTEM+'\\\\n篇幅合同：每个findings.evidence不超过600个字符，next_safe_step不超过250个字符；只保留定位与核心依据，不重复列出整份源码或叙述全部测试。不得省略任何claims的实际审阅或改变判断门。\\\\n'+'\\\\n输出协议硬要求：整个assistant文本第一个字符必须是{、最后一个字符必须是}。不要输出```或json代码围栏，不能输出JSON之前或之后的解释。以下仅为输出字段框架，标识/claims需逐字复制；它不是已经证明的事实，判定与证据必须实际审阅填写，不得将占位符原样输出。next_safe_step不可遗漏。\\\\n'+json.dumps(template,ensure_ascii=False)\\n    with tempfile.TemporaryDirectory(prefix='aos-review-b-system-') as cwd:\\n        gate.prepare_review_directory(cwd)\\n        command=gate.prime_command(cwd)\\n        command[command.index('--system-prompt')+1]=system\\n        proc=subprocess.run(command,input=json.dumps(request,ensure_ascii=False),env={'HOME':str(Path.home()),'PATH':str(Path(gate.NODE).parent)+':/usr/bin:/bin'},capture_output=True,text=True,timeout=120)\\n    gate.scan_secrets(proc.stdout);gate.scan_secrets(proc.stderr)\\n    transport={'returncode':proc.returncode,'stdout':proc.stdout,'stderr':proc.stderr}\\n    save(target.with_suffix('.transport.json'),transport)\\n    assert proc.returncode==0,'terminal failure; reconcile, no automatic retry'\\n    result=gate.parse_response(proc.stdout)  # Exact raw JSON; NEVER strip fences or repair.\\n    gate.validate_result(request,result);gate.validate_request(REPO,request)\\n    assert digest(Path(__file__))==own_sha and digest(Path(gate.__file__))==validator_sha\\n    save(target,{'schema':'aos-material-review-result/v1','mode':'tools-disabled-material-only',\\n        'runner_sha256':own_sha,'validator_sha256':validator_sha,'execution_authorized':False,'result':result})\\n    print(json.dumps({'result':str(target),'verdict':result['verdict'],'execution_authorized':False}))\\n\\nif __name__=='__main__':main()\\n\\nFILE .evidence/qyh-creator-lifecycle-bounded-reader-20261014/native-r1-result.json SHA f8d985ec387357305215b97173115c43d28f614d149bbbed2e2c24c71232e876\\n{\\n  \\\"containerId\\\": \\\"12daa903953018ee9f933721791e5f0885f8627519def55b269da2c1528ac183\\\",\\n  \\\"name\\\": \\\"qyh-creator-lifecycle-bounded-native-20261014-r1\\\",\\n  \\\"owner\\\": \\\"codex-01a13484-f019-7d82-94ce-812396db9124\\\",\\n  \\\"tmpfs\\\": true,\\n  \\\"observations\\\": [\\n    {\\n      \\\"role\\\": \\\"aos_runtime\\\",\\n      \\\"readonly\\\": \\\"on\\\",\\n      \\\"isolation\\\": \\\"repeatable read\\\"\\n    },\\n    {\\n      \\\"role\\\": \\\"aos_runtime\\\",\\n      \\\"readonly\\\": \\\"on\\\",\\n      \\\"isolation\\\": \\\"repeatable read\\\"\\n    },\\n    {\\n      \\\"role\\\": \\\"aos_runtime\\\",\\n      \\\"readonly\\\": \\\"on\\\",\\n      \\\"isolation\\\": \\\"repeatable read\\\"\\n    },\\n    {\\n      \\\"role\\\": \\\"aos_runtime\\\",\\n      \\\"readonly\\\": \\\"on\\\",\\n      \\\"isolation\\\": \\\"repeatable read\\\"\\n    }\\n  ],\\n  \\\"snapshotFirst\\\": 1,\\n  \\\"snapshotAfterConcurrentCommit\\\": 2,\\n  \\\"forceRlsForeignRowInvisible\\\": true,\\n  \\\"writeDeniedSqlstate\\\": \\\"25006\\\",\\n  \\\"badPayloadRejected\\\": \\\"CREATOR_LIFECYCLE_READ_AUTHORITY_DRIFT\\\",\\n  \\\"normalCompleteSnapshot\\\": true,\\n  \\\"originalVolumeTouched\\\": false,\\n  \\\"originalUserOrBudgetApproval\\\": false,\\n  \\\"currentSourceSha256\\\": \\\"95cacb071c8f9b10ad4ba3277c1a2820db076ba527c53d6d964b801fd01b7780\\\"\\n}\\n\\nFILE services/aos-api/aos_api/ecommerce_workshop_creator_lifecycle_readonly.py SHA 95cacb071c8f9b10ad4ba3277c1a2820db076ba527c53d6d964b801fd01b7780\\n\\\"\\\"\\\"Bounded saved-authority projection; never admits creator operations.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime\\nfrom typing import Any\\n\\nimport psycopg\\nfrom psycopg import IsolationLevel\\n\\nfrom aos_api.db import connect_read_only\\nfrom aos_api.ecommerce_workshop_creator_lifecycle import (\\n    CreatorBatchStartDecisionRevision, CreatorContractRevision,\\n    CreatorDeliveryObservation, CreatorLaneObservation, CreatorLifecycleView,\\n    CreatorRelationshipRevision, _ledger,\\n)\\nfrom aos_api.tenant_scope import TenantScope\\n\\nMAX_ROWS = 1000\\nMAX_ITEM_BYTES = 64 * 1024\\nMAX_TOTAL_BYTES = 1024 * 1024\\n\\n# Server-owned identifiers. Neither requests nor stored JSON choose a query.\\n_SPECS = {\\n    'start': ('ecommerce_creator_batch_start_decision_revision', 'decision_id',\\n              CreatorBatchStartDecisionRevision, 'started_at'),\\n    'lane': ('ecommerce_creator_lane_observation', 'observation_id',\\n             CreatorLaneObservation, 'observed_at'),\\n    'contract': ('ecommerce_creator_contract_revision', 'collaboration_id',\\n                 CreatorContractRevision, 'created_at'),\\n    'delivery': ('ecommerce_creator_delivery_observation', 'observation_id',\\n                 CreatorDeliveryObservation, 'observed_at'),\\n    'relationship': ('ecommerce_creator_relationship_revision', 'relationship_id',\\n                     CreatorRelationshipRevision, 'created_at'),\\n}\\n\\n\\nclass CreatorLifecycleReadonlyError(RuntimeError):\\n    def __init__(self, code: str):\\n        self.code = code\\n        super().__init__(code)\\n\\n\\ndef _deny(suffix: str):\\n    raise CreatorLifecycleReadonlyError('CREATOR_LIFECYCLE_READ_' + suffix)\\n\\n\\nclass CreatorLifecycleReadonlyReader:\\n    def __init__(self, *, connect_factory=None):\\n        self._connect = connect_factory or connect_read_only\\n\\n    @staticmethod\\n    def _rows(conn, scope, cutoff, kind, decision_id=None):\\n        table, identity, _, _ = _SPECS[kind]\\n        extra_column = 'decision_id,' if kind == 'lane' else ''\\n        extra_filter = ' AND decision_id=%s' if kind == 'lane' else ''\\n        direction = ' DESC' if kind == 'start' else ''\\n        limit = 1 if kind == 'start' else MAX_ROWS + 1\\n        sql = (\\n            f'SELECT org_id,project_id,{identity} AS entity_id,revision,content_hash,created_at,'\\n            f'{extra_column}octet_length(authority_data::text) AS authority_bytes,'\\n            f'CASE WHEN octet_length(authority_data::text)<={MAX_ITEM_BYTES} '\\n            'THEN authority_data ELSE NULL END AS authority_data '\\n            f'FROM {table} WHERE org_id=%s AND project_id=%s AND created_at<=%s'\\n            f'{extra_filter} ORDER BY created_at{direction},revision{direction},{identity}{direction} LIMIT %s'\\n        )\\n        params = (*scope.key, cutoff)\\n        if kind == 'lane':\\n            params = (*params, decision_id)\\n        rows = conn.execute(sql, (*params, limit)).fetchall()\\n        if len(rows) > MAX_ROWS or kind == 'start' and len(rows) > 1:\\n            _deny('LIMIT_EXCEEDED')\\n        return rows\\n\\n    @staticmethod\\n    def _decode(row, kind, scope, cutoff, total):\\n        _, _, model, timestamp = _SPECS[kind]\\n        size = row['authority_bytes']\\n        if type(size) is not int or size < 1:\\n            _deny('AUTHORITY_DRIFT')\\n        if size > MAX_ITEM_BYTES or total + size > MAX_TOTAL_BYTES:\\n            _deny('LIMIT_EXCEEDED')\\n        value = model.model_validate(row['authority_data'])\\n        # Delivery observations are append-only v1; their DTO has no revision.\\n        revision = 1 if kind == 'delivery' else value.revision\\n        if ((row['org_id'], row['project_id']) != scope.key\\n                or (value.tenant.org_id, value.tenant.project_id) != scope.key\\n                or value.content_hash != row['content_hash']\\n                or type(row['revision']) is not int or revision != row['revision']):\\n            _deny('AUTHORITY_DRIFT')\\n        identity = {\\n            'start': 'decision_id', 'lane': 'observation_id',\\n            'contract': 'collaboration_id', 'delivery': 'observation_id',\\n            'relationship': 'relationship_id',\\n        }[kind]\\n        created = row['created_at']\\n        observed = getattr(value, timestamp)\\n        if (getattr(value, identity) != row['entity_id']\\n                or not isinstance(created, datetime) or created.utcoffset() is None\\n                or observed.utcoffset() is None or observed != created or created > cutoff):\\n            _deny('AUTHORITY_DRIFT')\\n        return value, total + size\\n\\n    def read(self, scope: TenantScope) -> CreatorLifecycleView:\\n        try:\\n            with self._connect(scope) as conn:\\n                if (conn.read_only is not True or conn.autocommit is not False\\n                        or conn.isolation_level != IsolationLevel.REPEATABLE_READ):\\n                    _deny('CONNECTION_INVALID')\\n                cutoff = conn.execute('SELECT transaction_timestamp() AS cutoff').fetchone()['cutoff']\\n                if not isinstance(cutoff, datetime) or cutoff.utcoffset() is None:\\n                    _deny('AUTHORITY_DRIFT')\\n                total = 0\\n                values: dict[str, list[Any]] = {}\\n                for kind in _SPECS:\\n                    start = values.get('start', [])\\n                    rows = ([] if kind == 'lane' and not start else\\n                            self._rows(conn, scope, cutoff, kind,\\n                                       start[0].decision_id if kind == 'lane' else None))\\n                    values[kind] = []\\n                    for row in rows:\\n                        value, total = self._decode(row, kind, scope, cutoff, total)\\n                        if kind == 'lane':\\n                            current = start[0]\\n                            ref = value.start_decision_ref\\n                            if (row['decision_id'] != current.decision_id\\n                                    or ref.resource_type != 'CreatorBatchStartDecisionRevision'\\n                                    or ref.resource_id != current.decision_id\\n                                    or ref.revision != current.revision\\n                                    or ref.content_hash != current.content_hash\\n                                    or value.lane_id not in {lane.lane_id for lane in current.lanes}):\\n                                _deny('AUTHORITY_DRIFT')\\n                        values[kind].append(value)\\n                start = values['start'][0] if values['start'] else None\\n                lanes = list(start.lanes) if start else []\\n                latest = {observation.lane_id: observation for observation in values['lane']}\\n                if start:\\n                    lanes = [lane.model_copy(update={\\n                        'outcome': latest[lane.lane_id].outcome,\\n                        'resolved_outcome': latest[lane.lane_id].resolved_outcome,\\n                        'action_receipt_ref': latest[lane.lane_id].action_receipt_ref,\\n                    }) if lane.lane_id in latest else lane for lane in lanes]\\n                    start = start.model_copy(update={\\n                        'lanes': lanes, 'ledger': _ledger(lanes, start.ledger.eligible_items),\\n                    })\\n                result = CreatorLifecycleView(\\n                    tenant=dict(orgId=scope.org_id, projectId=scope.project_id),\\n                    evaluatedAt=cutoff, latestStart=start,\\n                    ledger=_ledger(lanes, start.ledger.eligible_items if start else 0),\\n                    contracts=values['contract'], deliveries=values['delivery'],\\n                    relationships=values['relationship'],\\n                    blockers=list(start.operational_blockers) if start else ['CREATOR_BATCH_START_NOT_AVAILABLE'],\\n                    allowedCommands=[], externalEffectsAllowed=False,\\n                )\\n                if len(result.model_dump_json(by_alias=True).encode('utf-8')) > MAX_TOTAL_BYTES:\\n                    _deny('LIMIT_EXCEEDED')\\n                return result\\n        except CreatorLifecycleReadonlyError:\\n            raise\\n        except psycopg.Error:\\n            _deny('UNAVAILABLE')\\n        except (ValueError, KeyError, TypeError, AttributeError):\\n            _deny('AUTHORITY_DRIFT')\\n\\nFILE services/aos-api/aos_api/ecommerce_workshop_read_catalog.py SHA 041b25f128c8c458890a54a7631751038d8bb9ee238134c35b590d5a59b9d77d\\n\\\"\\\"\\\"GET admission candidate over a current, signed, explicitly selected installation.\\n\\nThis adapter does not activate HTTP routes or grant runtime readiness. Legacy\\nadmission is preserved; selected installed assets require actual exact scope grants.\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nfrom aos_api.asset_registry.errors import AssetNotFoundError\\nfrom aos_api.ecommerce_workshop_contracts import WorkshopDependencyType\\n\\n\\nclass EcommerceWorkshopReadCatalog:\\n    def __init__(self, *, legacy, installed=None, installed_factory=None) -> None:\\n        self._legacy = legacy\\n        self._installed = installed\\n        self._installed_factory = installed_factory\\n\\n    def get_readiness(self, **scope):\\n        try:\\n            return self._legacy.get_readiness(**scope)\\n        except AssetNotFoundError:\\n            # Integrity, signature and availability errors never permit fallback.\\n            pass\\n        return self.get_installed_readiness(**scope)\\n\\n    def get_installed_readiness(self, **scope):\\n        \\\"\\\"\\\"Check only the selected installation with the existing exact read gate.\\\"\\\"\\\"\\n        installed = (\\n            self._installed_factory() if self._installed_factory is not None\\n            else self._installed\\n        )\\n        result = installed.get_readiness(**scope)\\n        item = result.item\\n        installation = item.installation_ref\\n        required = set(item.permissions.data_scopes)\\n        expected_revision = (\\n            f'installation:{installation.revision}/lock:{installation.lock_revision}'\\n        )\\n        granted = {\\n            ref.resource_id for ref in item.dependency_refs\\n            if ref.resource_type == 'DataScopeGrant'\\n            and ref.revision == expected_revision\\n            and ref.content_hash == installation.lock_hash\\n            and ref.authority == 'postgres:bundle_composition_lock'\\n        }\\n        permitted_gap_types = {\\n            WorkshopDependencyType.OBJECT,\\n            WorkshopDependencyType.CAPABILITY,\\n            WorkshopDependencyType.AIP_FEATURE,\\n        }\\n        disallowed = any(\\n            blocker.dependency_type not in permitted_gap_types\\n            and not (\\n                blocker.dependency_type == WorkshopDependencyType.INSTALLATION\\n                and blocker.reason_code == 'INSTALLED_ASSET_READONLY'\\n                and blocker.dependency_id == installation.installation_id\\n            )\\n            for blocker in item.blockers\\n        )\\n        if 'ecommerce.workshop.read' not in required or not required <= granted or disallowed:\\n            raise AssetNotFoundError('Workshop module is not installed for scoped reading')\\n        # Keep the original disabled state and every runtime/authority gap intact.\\n        return result\\n\\nFILE services/aos-api/tests/test_ecommerce_workshop_read_http.py SHA a75585bac5c1b4bd1895340e3567de62089da350ecae3216e54fe7e52a4bfef3\\n\\\"\\\"\\\"HTTP scope fence: only explicitly audited GETs use installed read admission.\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom fastapi import FastAPI\\nfrom fastapi.testclient import TestClient\\n\\nfrom aos_api.asset_registry.errors import AssetNotFoundError\\nfrom aos_api.auth import Principal, require_principal\\nfrom aos_api.errors import register_exception_handlers\\nfrom aos_api.routers import ecommerce_workshop as routes\\n\\nROOTS = {\\n    'task-cockpit', 'operations', 'content-campaign', 'creator-growth',\\n    'media-studio', 'analyst', 'price-governance', 'customer',\\n}\\n\\n\\nclass RejectingCatalog:\\n    def __init__(self):\\n        self.calls = []\\n\\n    def get_readiness(self, **scope):\\n        self.calls.append(scope)\\n        raise AssetNotFoundError('not installed in current scoped catalog')\\n\\n\\ndef client_with_catalogs():\\n    app = FastAPI()\\n    register_exception_handlers(app)\\n    app.include_router(routes.router)\\n    legacy, reader = RejectingCatalog(), RejectingCatalog()\\n    app.dependency_overrides[routes.get_ecommerce_workshop_catalog] = lambda: legacy\\n    app.dependency_overrides[routes.get_ecommerce_workshop_read_catalog] = lambda: reader\\n    app.dependency_overrides[require_principal] = lambda: Principal(\\n        subject='scope-test', org_id='org-org', project_id='dev-project',\\n        roles=['admin'], markings=[],\\n    )\\n    return TestClient(app), legacy, reader\\n\\n\\n@pytest.mark.parametrize('module', sorted(ROOTS))\\ndef test_root_get_uses_scoped_read_admission_before_business_reader(module):\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get(f'/v1/ecommerce-workshop/views/{module}')\\n    assert response.status_code == 404\\n    assert not legacy.calls\\n    assert len(reader.calls) == 1\\n    assert reader.calls[0] == dict(module_id=f'ecommerce.{module}',\\n        org_id='org-org', project_id='dev-project', roles=['admin'], markings=[])\\n\\n\\n@pytest.mark.parametrize('path', [\\n    '/views/customer/contributions', '/views/creator-growth/lifecycle',\\n    '/modules/ecommerce.operations/readiness',\\n])\\ndef test_unreviewed_get_still_uses_legacy_admission(path):\\n    client, legacy, reader = client_with_catalogs()\\n    response = client.get('/v1/ecommerce-workshop' + path)\\n    assert response.status_code == 404\\n    assert legacy.calls\\n    assert not reader.calls\\n\\n\\ndef test_read_dependency_only_reaches_explicit_audited_get_routes():\\n    actual = set()\\n    for route in routes.router.routes:\\n     